// StripMarkers removes every Sedum marker line from content, leaving all other lines unchanged.
func StripMarkers(comment genpkg.Comment, content string) string {
	if comment.Prefix == "" {
		return content
	}
	open := comment.Prefix + " sedum:"
	closing := comment.Prefix + " /sedum:"
	var b strings.Builder
	for _, line := range strings.SplitAfter(content, "\n") {
		trimmed := strings.TrimLeft(line, " \t")
		if strings.HasPrefix(trimmed, open) || strings.HasPrefix(trimmed, closing) {
			continue
		}
		b.WriteString(line)
	}
	return b.String()
}

// VerifyError reports the first line where a round trip differs.
type VerifyError struct {
	Line int
	Want string
	Got  string
}

// Error describes the differing line.
func (e *VerifyError) Error() string {
	return fmt.Sprintf("round trip: line %d differs: want \"%s\" got \"%s\"", e.Line, e.Want, e.Got)
}

// Verify checks that adopted, with its Sedum markers removed, matches original line by line.
// Blank lines are ignored and trailing whitespace is trimmed.
func Verify(comment genpkg.Comment, original, adopted string) error {
	significant := func(s string) []string {
		var out []string
		for _, line := range strings.Split(s, "\n") {
			line = strings.TrimRight(line, " \t\r")
			if line != "" {
				out = append(out, line)
			}
		}
		return out
	}
	want := significant(original)
	got := significant(StripMarkers(comment, adopted))
	for i := 0; i < len(want) || i < len(got); i++ {
		w := "<end of file>"
		if i < len(want) {
			w = want[i]
		}
		g := "<end of file>"
		if i < len(got) {
			g = got[i]
		}
		if w != g {
			return &VerifyError{Line: i + 1, Want: w, Got: g}
		}
	}
	return nil
}

func TestStripMarkers(t *testing.T) {
	in := "package p

// sedum:anchor:decls
// sedum:setFunction {"a":1}
func f() {}

// /sedum:setFunction
"
	want := "package p

func f() {}

"
	got := StripMarkers(genpkg.Comment{Prefix: "//"}, in)
	if got != want {
		t.Errorf("StripMarkers() = %q, want %q", got, want)
	}
}

func TestStripMarkersKeepsIndentedMarkerLookalikes(t *testing.T) {
	in := "\tx := \"// sedum:\"\n\t// sedum:setFunction {}\n"
	want := "\tx := \"// sedum:\"\n"
	got := StripMarkers(genpkg.Comment{Prefix: "//"}, in)
	if got != want {
		t.Errorf("StripMarkers() = %q, want %q", got, want)
	}
}

func TestVerifyIgnoresBlankLines(t *testing.T) {
	original := "a
b
"
	adopted := "a

// sedum:x {}
b
// /sedum:x

"
	if err := Verify(genpkg.Comment{Prefix: "//"}, original, adopted); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestVerifyReportsFirstDifference(t *testing.T) {
	err := Verify(genpkg.Comment{Prefix: "//"}, "a\nb\nc\n", "a\nB\nc\n")
	var verr *VerifyError
	if !errors.As(err, &verr) {
		t.Fatalf("want *VerifyError, got %v", err)
	}
	if verr.Line != 2 || verr.Want != "b" || verr.Got != "B" {
		t.Errorf("got %+v", *verr)
	}
}

func TestVerifyLengthMismatch(t *testing.T) {
	err := Verify(genpkg.Comment{Prefix: "//"}, "a\nb\n", "a\n")
	var verr *VerifyError
	if !errors.As(err, &verr) {
		t.Fatalf("want *VerifyError, got %v", err)
	}
	if verr.Line != 2 || verr.Want != "b" || verr.Got != "<end of file>" {
		t.Errorf("got %+v", *verr)
	}
	err = Verify(genpkg.Comment{Prefix: "//"}, "a\n", "a\nb\n")
	if !errors.As(err, &verr) {
		t.Fatalf("want *VerifyError, got %v", err)
	}
	if verr.Want != "<end of file>" {
		t.Errorf("got %+v", *verr)
	}
}

func TestVerifyLeadingWhitespaceMatters(t *testing.T) {
	if err := Verify(genpkg.Comment{Prefix: "//"}, "a\n\tb\n", "a\n    b\n"); err == nil {
		t.Error("expected a difference for changed leading whitespace")
	}
}

